const p = msg.payload;
if (p && p.source === 'critical') {
    // Alarm, then re-arm the latched interrupt-mode Alert.
    return [{ payload: 'ALARM: freezer above -5 °C - door left open?' },
            { payload: { clear_interrupt: true } }];
}
if (p && p.temperature_c !== undefined) {
    msg.payload = `${p.temperature_c.toFixed(2)} °C` + (p.alert_asserted ? ' (alert asserted)' : '');
    return [msg, null];
}
return null;
